ALTER TABLE public.stories ADD COLUMN mentions jsonb NOT NULL DEFAULT '[]'::jsonb;
CREATE OR REPLACE FUNCTION public.community_members(search_text text DEFAULT '', member_id uuid DEFAULT NULL) RETURNS TABLE(id uuid,display_name text,business_name text,avatar_url text,city text,account_role text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p.id,p.display_name,p.business_name,p.avatar_url,p.city,p.account_role FROM public.profiles p WHERE auth.uid() IS NOT NULL AND NOT public.is_account_banned(auth.uid()) AND NOT public.is_account_banned(p.id) AND coalesce(p.account_status,'active')='active' AND (member_id IS NULL OR p.id=member_id) AND (p.display_name ILIKE '%' || left(search_text,80) || '%' OR coalesce(p.business_name,'') ILIKE '%' || left(search_text,80) || '%') ORDER BY p.display_name,p.id LIMIT 10 $$;
REVOKE ALL ON FUNCTION public.community_members(text,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.community_members(text,uuid) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.validate_story_mentions() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE m jsonb; BEGIN IF jsonb_typeof(NEW.mentions)<>'array' OR jsonb_array_length(NEW.mentions)>60 THEN RAISE EXCEPTION 'התיוגים אינם תקינים'; END IF; FOR m IN SELECT value FROM jsonb_array_elements(NEW.mentions) LOOP IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=(m->>'userId')::uuid) OR length(m->>'label') NOT BETWEEN 1 AND 120 OR (m->>'label') ~ '[<>]' OR NOT (m ?& ARRAY['x','y','width','height']) OR (m->>'x')::numeric NOT BETWEEN 0 AND 100 OR (m->>'y')::numeric NOT BETWEEN 0 AND 100 OR (m->>'width')::numeric NOT BETWEEN 0.01 AND 100 OR (m->>'height')::numeric NOT BETWEEN 0.01 AND 100 THEN RAISE EXCEPTION 'התיוגים אינם תקינים'; END IF; END LOOP; RETURN NEW; END $$;
CREATE TRIGGER story_mentions_validation BEFORE INSERT OR UPDATE ON public.stories FOR EACH ROW EXECUTE FUNCTION public.validate_story_mentions();